#version 300 es
uniform vec2 uResolution;
uniform vec2 uPlaneSize;
uniform vec4 uMatrixAB;
uniform vec2 uMatrixT;
out vec2 vLocal;
out vec2 vPixel;
void main() {
  vec2 corner = vec2(float(gl_VertexID & 1), float((gl_VertexID >> 1) & 1));
  vLocal = corner;
  vec2 local = corner * uPlaneSize;
  vPixel = vec2(
    uMatrixAB.x * local.x + uMatrixAB.z * local.y + uMatrixT.x,
    uMatrixAB.y * local.x + uMatrixAB.w * local.y + uMatrixT.y
  );
  gl_Position = vec4(vPixel.x / uResolution.x * 2.0 - 1.0, 1.0 - vPixel.y / uResolution.y * 2.0, 0.0, 1.0);
}

#version 300 es
precision highp float;
in vec2 vLocal;
in vec2 vPixel;
uniform sampler2D uTexture;
uniform vec4 uClip;
uniform vec4 uClipRadius;
uniform vec4 uUv;
uniform float uAlpha;
uniform vec2 uPlaneSize;
uniform float uDecorOn;
uniform vec4 uRadius;
uniform float uBorderWidth;
uniform vec4 uBorderColor;
uniform float uGradientOn;
uniform vec4 uGradientA;
uniform vec4 uGradientB;
uniform vec4 uGradientGeom;
out vec4 outColor;

vec4 sampleAt(vec2 local) {
  return texture(uTexture, uUv.xy + (local / uPlaneSize) * uUv.zw);
}

float sdRoundedBox(vec2 p, vec2 b, vec4 r) {
  vec2 pair = (p.x > 0.0) ? r.yz : r.xw;
  float rad = (p.y > 0.0) ? pair.y : pair.x;
  vec2 q = abs(p) - b + rad;
  return min(max(q.x, q.y), 0.0) + length(max(q, vec2(0.0))) - rad;
}

bool insidePlane(vec2 local) {
  return local.x >= 0.0 && local.x <= uPlaneSize.x && local.y >= 0.0 && local.y <= uPlaneSize.y;
}

void main() {
  if (vPixel.x < uClip.x || vPixel.x > uClip.x + uClip.z) discard;
  if (vPixel.y < uClip.y || vPixel.y > uClip.y + uClip.w) discard;

  float clipCoverage = 1.0;
  if (dot(uClipRadius, vec4(1.0)) > 0.0) {
    vec2 clipHalf = uClip.zw * 0.5;
    float clipDistance = sdRoundedBox(
      vPixel - (uClip.xy + clipHalf),
      clipHalf,
      uClipRadius
    );
    clipCoverage = clamp(0.5 - clipDistance, 0.0, 1.0);
    if (clipCoverage <= 0.0) discard;
  }

  vec2 local = vLocal * uPlaneSize;
  vec4 base = sampleAt(local);

  if (uDecorOn > 0.5) {
    vec2 halfSize = uPlaneSize * 0.5;
    float d = sdRoundedBox(local - halfSize, halfSize, uRadius);
    float outer = clamp(0.5 - d, 0.0, 1.0);
    float inner = clamp(0.5 - (d + uBorderWidth), 0.0, 1.0);
    vec4 fill = base;
    if (uGradientOn > 0.5) {
      float t = dot(local / uPlaneSize, uGradientGeom.xy);
      float span = uGradientGeom.w - uGradientGeom.z;
      float k = span == 0.0
        ? step(uGradientGeom.z, t)
        : clamp((t - uGradientGeom.z) / span, 0.0, 1.0);
      fill = mix(uGradientA, uGradientB, k);
    }
    base = fill * inner + uBorderColor * (outer - inner);
  }

  outColor = base * uAlpha * clipCoverage;
}

