#version 300 es
precision highp float;
in vec2 vScreen;
uniform sampler2D uTexture;
uniform vec2 uResolution;
uniform vec2 uPointer;
uniform float uRadius;
uniform float uStrength;
uniform float uCurve;
uniform float uCurveX;
uniform float uCurvePower;
uniform float uCurveEdge;
uniform vec2 uPulse;
uniform float uPulseRadius;
uniform float uPulseWidth;
uniform float uPulseAmplitude;
out vec4 outColor;

vec3 sampleScreen(vec2 point) {
  vec2 uv = vec2(point.x / uResolution.x, 1.0 - point.y / uResolution.y);
  return texture(uTexture, uv).rgb;
}

void main() {
  vec2 delta = vScreen - uPointer;
  float distance = length(delta) / uRadius;
  float spot = exp(-distance * distance * 2.0);

  float band = max(uCurveEdge, 0.001);
  float bowY = 0.0;
  if (uCurve != 0.0) {
    float across = max(sin(3.14159265 * vScreen.x / uResolution.x), 0.0);
    float edge =
      smoothstep(0.0, band, vScreen.y) *
      smoothstep(0.0, band, uResolution.y - vScreen.y);
    bowY = uCurve * pow(across, uCurvePower) * edge;
  }
  float bowX = 0.0;
  if (uCurveX != 0.0) {
    float down = max(sin(3.14159265 * vScreen.y / uResolution.y), 0.0);
    float edge =
      smoothstep(0.0, band, vScreen.x) *
      smoothstep(0.0, band, uResolution.x - vScreen.x);
    bowX = uCurveX * pow(down, uCurvePower) * edge;
  }

  vec2 ring = vec2(0.0);
  if (uPulseAmplitude != 0.0) {
    vec2 pulseDelta = vScreen - uPulse;
    float pulseDistance = length(pulseDelta);
    float thickness = max(uPulseWidth * uPulseRadius, 1.0);
    float falloff = (pulseDistance - uPulseRadius) / thickness;
    ring =
      (pulseDelta / max(pulseDistance, 1.0)) *
      (uPulseAmplitude * exp(-falloff * falloff));
  }

  vec2 source = vScreen - delta * (spot * uStrength) - vec2(bowX, bowY) - ring;

  vec3 color = sampleScreen(source);

  outColor = vec4(color, 1.0);
}

